// Escalation rules engine
const data = items[0].json;
const riskCategory = data.risk_category;
const riskScore = data.risk_score || 0;
const symptoms = data.symptoms || [];
const vitals = data.vitals || {};

// Define escalation tiers
const escalationTiers = {
  tier_1: {
    level: 'standard',
    notify: ['primary_physician'],
    urgency: 'routine',
    response_time_hours: 48
  },
  tier_2: {
    level: 'elevated',
    notify: ['primary_physician', 'nurse_coordinator'],
    urgency: 'priority',
    response_time_hours: 24
  },
  tier_3: {
    level: 'urgent',
    notify: ['primary_physician', 'specialist', 'nurse_coordinator'],
    urgency: 'urgent',
    response_time_hours: 4
  },
  tier_4: {
    level: 'critical',
    notify: ['emergency_team', 'primary_physician', 'specialist', 'department_head'],
    urgency: 'emergency',
    response_time_hours: 1
  }
};

// Escalation logic
let escalationTier = 'tier_1';
let escalationReasons = [];

// Critical symptoms check
const criticalSymptoms = ['chest_pain', 'difficulty_breathing', 'severe_bleeding', 'loss_of_consciousness'];
const hasCriticalSymptom = symptoms.some(s => criticalSymptoms.includes(s));

if (hasCriticalSymptom) {
  escalationTier = 'tier_4';
  escalationReasons.push('Critical symptom detected');
}

// Vital signs check
if (vitals.systolic_bp >= 180 || vitals.systolic_bp <= 90) {
  escalationTier = escalationTier === 'tier_4' ? 'tier_4' : 'tier_3';
  escalationReasons.push('Critical blood pressure');
}

if (vitals.heart_rate >= 120 || vitals.heart_rate <= 50) {
  escalationTier = escalationTier === 'tier_4' ? 'tier_4' : 'tier_3';
  escalationReasons.push('Abnormal heart rate');
}

// Risk score check
if (riskScore >= 0.9 && escalationTier === 'tier_1') {
  escalationTier = 'tier_3';
  escalationReasons.push('Very high risk score');
} else if (riskScore >= 0.7 && escalationTier === 'tier_1') {
  escalationTier = 'tier_2';
  escalationReasons.push('High risk score');
}

// Risk category override
if (riskCategory === 'very_high' && escalationTier === 'tier_1') {
  escalationTier = 'tier_3';
  escalationReasons.push('Very high risk category');
}

// Time-based escalation (if no response within expected time)
if (data.previous_escalation) {
  const hoursSinceLastEscalation = (Date.now() - new Date(data.previous_escalation.timestamp).getTime()) / (1000 * 60 * 60);
  const expectedResponseTime = escalationTiers[data.previous_escalation.tier].response_time_hours;

  if (hoursSinceLastEscalation >= expectedResponseTime && !data.previous_escalation.responded) {
    // Escalate to next tier
    const currentTierNum = parseInt(data.previous_escalation.tier.split('_')[1]);
    const nextTierNum = Math.min(currentTierNum + 1, 4);
    escalationTier = `tier_${nextTierNum}`;
    escalationReasons.push('No response within expected timeframe');
  }
}

const escalation = escalationTiers[escalationTier];

return [{
  json: {
    patient_id: data.patient_id,
    escalation_tier: escalationTier,
    escalation_level: escalation.level,
    urgency: escalation.urgency,
    notify_roles: escalation.notify,
    response_time_hours: escalation.response_time_hours,
    reasons: escalationReasons,
    risk_category: riskCategory,
    risk_score: riskScore,
    symptoms: symptoms,
    vitals: vitals,
    escalated_at: new Date().toISOString()
  }
}];

// Generate multi-tier notification list
const notifyRoles = items[0].json.notify_roles;
const patientId = items[0].json.patient_id;
const escalationTier = items[0].json.escalation_tier;
const urgency = items[0].json.urgency;

// Fetch care team members for each role (simulated)
const careTeamDirectory = {
  primary_physician: [{email: 'dr.smith@mediczy.com', phone: '+1234567890', sms: true, call: true}],
  specialist: [{email: 'dr.jones@mediczy.com', phone: '+1234567891', sms: true, call: true}],
  nurse_coordinator: [{email: 'nurse.jane@mediczy.com', phone: '+1234567892', sms: true, call: false}],
  emergency_team: [
    {email: 'emergency@mediczy.com', phone: '+1234567893', sms: true, call: true},
    {email: 'oncall@mediczy.com', phone: '+1234567894', sms: true, call: true}
  ],
  department_head: [{email: 'dept.head@mediczy.com', phone: '+1234567895', sms: false, call: true}]
};

const notifications = [];

for (const role of notifyRoles) {
  const members = careTeamDirectory[role] || [];
  for (const member of members) {
    notifications.push({
      recipient: member.email,
      phone: member.phone,
      role: role,
      channels: [
        'email',
        ...(member.sms ? ['sms'] : []),
        ...(urgency === 'emergency' && member.call ? ['phone_call'] : []),
        'push'
      ],
      patient_id: patientId,
      escalation_tier: escalationTier,
      urgency: urgency,
      message: `ESCALATION ${escalationTier.toUpperCase()}: Patient ${patientId} requires ${urgency} attention. Reasons: ${items[0].json.reasons.join(', ')}`
    });
  }
}

return notifications.map(n => ({json: n}));
